mapper.select:
select waits.*, waits.id::text as id_text from (
    select c.id, 'CALENDAR'::text as wait_type, c.tenant_id,
           c.calendar_code as subject_code, c.biz_date, c.wait_status,
           c.dependency_snapshot::text as dependency_snapshot,
           c.blocked_reason as reason, c.updated_at, null::text as request_id
      from batch.calendar_dependency_wait c where c.tenant_id = #{query.tenantId}
    union all
    select j.id, 'JOB'::text, j.tenant_id, j.job_code, j.biz_date, j.wait_status,
           j.dependency_snapshot::text, j.last_not_ready_reason, j.updated_at, j.request_id
      from batch.job_dependency_waiting_launch j where j.tenant_id = #{query.tenantId}
    union all
    select r.id, 'READINESS'::text, r.tenant_id, r.workflow_code, r.biz_date, r.wait_status,
           r.depends_on_job_codes, r.last_error_code, r.updated_at, r.request_id
      from batch.readiness_wait r where r.tenant_id = #{query.tenantId}
    union all
    select w.id, 'CAPACITY_ADMISSION'::text, w.tenant_id, d.workflow_code, w.biz_date,
           w.wait_status, null::text, 'CAPACITY_LIMIT'::text, w.updated_at, w.request_id
      from batch.workflow_launch_wait w
      join batch.workflow_definition d on d.tenant_id = w.tenant_id and d.id = w.workflow_definition_id
     where w.tenant_id = #{query.tenantId}
) waits
where 1 = 1
and wait_type = #{query.waitType}
and wait_status = #{query.waitStatus}
and biz_date >= #{query.bizDateFrom}
and biz_date <= #{query.bizDateTo}

    and (wait_type collate "C", id) > (cast(#{query.cursorType} as text) collate "C", cast(#{query.cursorId} as bigint))

order by wait_type collate "C", id
limit #{limit}
